            f'            <p class="dpick__series mono">{series}</p>\n'
            f'            <h3>{name}</h3>\n'
            f'            <div class="dpick__specs"><span class="dpick__screen">{meta.split(" &middot; ")[0]}</span><span>{cpu_disp}</span><span>16GB RAM &middot; new 1TB Samsung 990 PRO</span></div>\n'
