def build_new_page(d):
    faqs = [(f['q'], f['a']) if isinstance(f, dict) else tuple(f) for f in d['faqs']]
    _blocks = [_sec_block(s, i) for i, s in enumerate(d['sections'])]
    if d['slug'] in VICTRON_CRED_SLUGS:
        _blocks.insert(0, VICTRON_CRED_BAND)
    # help-ASAP funnel: problem-intent pages get the SOS band right after section 1
    if _wants_sos_band(d['slug']) and len(_blocks) > 1:
        _blocks.insert(1, bp.SOS_BAND)
    # learning funnel: gentle pages promote the free courses at the end
    if _wants_courses_band(d['slug']):
        _blocks.append(bp.COURSES_BAND)
    # AEO comparison table: high-value "vs"/"which" pages get an at-a-glance table after section 1
    _cmp = DELL_COMPARE_TABLES.get(d['slug'])
    if _cmp:
        _cmp_head, _cmp_html = _cmp
        _cmp_block = f'''    <section class="section section--alt" aria-label="At a glance">
      <div class="wrap" data-reveal>
        <div class="section-head"><h2 class="section-title section-title--center">{_cmp_head}<span class="title-underline title-underline--center"></span></h2></div>
        {_cmp_html}
      </div>
    </section>'''
        _blocks.insert(1 if len(_blocks) > 1 else len(_blocks), _cmp_block)
    if d['slug'] in ('onedrive-problems', 'outlook-problems'):
        _blocks.append(_office_cluster_section(exclude=(d['slug'],)))
    if d.get('refurbBands'):
        _blocks.append(REFURB_PRICE_RISE_BAND)
        _blocks.append(REFURB_SUPPORT_BAND)
        _blocks.append(_model_details_band(d['slug']))
        _blocks.append(_refurb_reserve_band(d['slug']))
    # optional at-a-glance answer table (generalised _cmp_block: list of (label, value) rows;
    # authored inline in the page dict or centrally in at_a_glance_data.py)
    _ag_src = d.get('atAGlance') or AT_A_GLANCE.get(d['slug'])
    if _ag_src:
        _ag_rows = "\n".join(f'              <tr><th scope="row">{l}</th><td>{v}</td></tr>' for l, v in _ag_src)
        _ag = f'''    <section class="section section--alt" aria-label="At a glance">
      <div class="wrap" data-reveal>
        <div class="section-head"><h2 class="section-title section-title--center">At a glance<span class="title-underline title-underline--center"></span></h2></div>
        <div class="price-table-wrap"><table class="price-table price-table--facts"><tbody>
{_ag_rows}
            </tbody></table></div>
      </div>
    </section>'''
        _blocks.insert(1 if len(_blocks) > 1 else len(_blocks), _ag)
    sections = "\n".join(_blocks)
    _is_course = ('-course' in d['slug']) or d['slug'].startswith('computer-lessons')
    toc = _toc_chips(d['sections']) if (not _is_course and len(d['sections']) >= 4) else ""
    trust = "" if _is_course else TRUST_LINE
    cross = ""
    if d.get('crossLinksHtml'):
        cross = _related_block(d['crossLinksHtml']) or f'''    <section class="section" aria-label="Related">
      <div class="wrap prose" data-reveal>
        <p class="eyebrow mono">// RELATED</p>
{d['crossLinksHtml']}
      </div>
    </section>'''
    _hubbox = ""
    if d['slug'] in ("outlook-problems",):
        _hubbox = '''    <section class="section" aria-label="Search" style="padding-top:0">
      <div class="wrap" style="display:flex;justify-content:center">
        <button type="button" class="search-box" data-search-open>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/></svg>
          <span class="search-box__txt">Search all Outlook fixes &amp; the whole site&hellip;</span>
          <kbd>/</kbd>
        </button>
      </div>
    </section>'''
    _hub = _pack_hub(d['slug'])
    _bch = bp.bc_sub(_hub[0], '/' + _hub[1] + '/', d['crumbName']) if _hub else bc(d['crumbName'])
    content = "\n".join(x for x in [
      hero(_bch, d['eyebrow'], d['h1'], hero_trust(d['lede']),
           cta1=tuple(d['primaryCta']), cta2=tuple(d['secondaryCta']), chips=list(d['chips']),
           scene=HERO_SCENES.get(_PACK_SCENE.get(d['slug']))),
      toc,
      _hubbox,
      sections,
      cross,
      trust,
      faq_html(faqs),
      cta(d['ctaHead'], d['ctaSub'], primary=tuple(d['primaryCta']), secondary=tuple(d['secondaryCta'])),
    ] if x)
    def schema(s, _d=d, _faqs=faqs, _hub=_hub):
        _c = bp.crumb_sub(s, _hub[0], _hub[1], _d['crumbName']) if _hub else crumb(s, _d['crumbName'])
        nodes = [_c, webpage(s, _d['crumbName'], _d['metaDesc'])]
        if _d.get('schemaKind') == 'service':
            _area = bp.WORLDWIDE_AREA if _d.get('worldwide') else None
            nodes.append(service(s, _d.get('serviceName', _d['crumbName']), _d['metaDesc'], _d.get('serviceName', _d['crumbName']), area=_area))
        if _d.get('howToSteps'):
            nodes.append(bp.howto_node(s, _d.get('howToName', _d['crumbName']), [(st['name'], st['text']) for st in _d['howToSteps']]))
        if _d.get('productOffer'):
            po = _d['productOffer']
            nodes.append({"@type": "Product", "@id": SITE + "/" + s + "/#product",
                          "name": po['name'], "description": po['description'],
                          "brand": {"@type": "Brand", "name": "Dell"},
                          "itemCondition": "https://schema.org/RefurbishedCondition",
                          "category": po.get('category', 'Refurbished computer hardware'),
                          "additionalProperty": [{"@type": "PropertyValue", "name": n, "value": v} for n, v in po.get('props', [])],
                          "offers": {"@type": "AggregateOffer", "priceCurrency": "GBP", "lowPrice": po['lowPrice'],
                                     "availability": "https://schema.org/InStock", "url": SITE + "/" + s + "/" + po.get('offerAnchor', ''),
                                     "seller": {"@type": "Organization", "name": "365 Techies"}},
                          "image": SITE + "/og-image.jpg", "url": SITE + "/" + s + "/"})
        nodes.append(faqpage(s, _faqs))
        return graph(nodes)
    add(slug=d['slug'], title=d['title'], desc=d['metaDesc'], og_title=d['ogTitle'], schema=schema, content=content)

